// return as number of seconds
function getTimeToSeconds(time) {
  var result = '';
  if (time === undefined || time === 0) {
    result = '0초';
  } else if (time > 60) {
    var sec = (time % 60).toFixed(0);
    var min = Math.floor(time % 3600 / 60);
    result = min + '분 ' + sec + '초';
  } else {
    result = Number(time).toFixed(1) + '초';
  }
  return result;
}

